    sorted_list = []
    lst_copy = lst.copy()

    while lst_copy:
        smallest = find_smallest_number(lst_copy)
        sorted_list.append(smallest)
        lst_copy.remove(smallest)

        if lst_copy:
            largest = find_largest_number(lst_copy)
