def strange_sort_list(lst):
    if not lst:
        return []

    sorted_lst = sorted(lst)
    small_list = []
    large_list = []

    for i, num in enumerate(sorted_lst):
        if i % 2 == 0:
            small_list.append(num)
        else:
            large_list.append(num)

    result = []
    for small, large in zip(small_list, large_list):
        result.extend([small, large])

    if len(small_list) > len(large_list):
        result.append(small_list[-1])

    return result

